import sys
from math import isqrt

def sum_of_divisors(n):
    total = 0
    root = isqrt(n)
    for i in range(1, root + 1):
        if n % i == 0:
            total += i
            if i != n // i:
                total += n // i
    return total

def count_solutions(A):
    count = 0
    for x in range(1, A + 1):
        if sum_of_divisors(x) == A:
            count += 1
    return count

A = int(sys.stdin.strip())
print(count_solutions(A))
